 569→/// Configuration for a named environment.
 570→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 571→#[serde(default)]
 572→pub struct EnvironmentConfig {
 573→    /// Rules for auto-detecting this environment.
 574→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 575→    pub detect: Vec<EnvironmentDetectRule>,
 576→
 577→    /// Default workflow to run in this environment.
 578→    #[serde(skip_serializing_if = "Option::is_none")]
 579→    pub default_workflow: Option<String>,
 580→
 581→    /// Requirements that are assumed to be satisfied in this environment.
 582→    /// These skip gap detection checks when this environment is active.
