 587→/// A rule for auto-detecting an environment.
 588→#[derive(Debug, Clone, Serialize, Deserialize)]
 589→pub struct EnvironmentDetectRule {
 590→    /// Environment variable name to check.
 591→    pub env: String,
 592→
 593→    /// If set, the variable must equal this value. If absent, just checks presence.
 594→    #[serde(skip_serializing_if = "Option::is_none")]
